        </div>
      </div>

      <div class="example">
        <button class="question" type="button" aria-expanded="false" aria-controls="answer-water" id="question-water">
          <span>Why does my cat need fresh water every day?</span>
          <span class="icon" aria-hidden="true">+</span>
        </button>
